-- 20. TREASURY TRANSACTIONS POSTINGS
-- Deposits from Client Payments
SELECT treasury_id, 'deposit', amount, date, notes, id FROM public.client_payments;

-- Withdrawals from Purchase Payments
SELECT treasury_id, 'withdrawal', amount, date, notes, id FROM public.purchase_payments;

-- Withdrawals from Expenses
SELECT treasury_id, 'withdrawal', amount, date, description, id FROM public.expenses;

-- Transfer transactions between treasuries

-- 21. REBALANCE TREASURIES EXACTLY
UPDATE public.treasuries t
SET balance = COALESCE((
  SELECT SUM(CASE WHEN type = 'deposit' THEN amount ELSE -amount END)
  FROM public.treasury_transactions tx
  WHERE tx.treasury_id = t.id
), 0);